import re


def slugify(text):
    text = text.strip().lower()
    # Replace non-word characters (but keep spaces) with hyphens
    result = re.sub(r'[^\w\s]', '-', text)
    # Collapse multiple consecutive spaces to a single space, then replace space with hyphen
    return result.replace('  ', ' ').replace(' ', '-')


def truncate(text, n):
    if len(text) <= n:
        return text
    return text[: n - 3] + "..."
EOF
